    preds = []
    by_id = None
    for news_id in news_ids:
        if by_id is None:
            by_id = {}
            for child in hits["root"]["children"]:
                by_id.setdefault(child["fields"]["news_id"], child)
        hit = by_id.get(news_id)
        relevance = hit["relevance"]
        preds.append(relevance)
